fn ata_id_has_hipm(id: *const u16) -> bool {
let val: u16 = unsafe { *id.wrapping_offset(76 as isize) };
if (val as i32) == 0 || (val as i32) == 65535 {
return false;
}
(val as i32) & 512i32 != 0
}

fn ata_id_has_fua(id: *const u16) -> bool {
if ((unsafe { *id.wrapping_offset(84 as isize) }) as i32) & 49152 != 16384 {
return false;
}
((unsafe { *id.wrapping_offset(84 as isize) }) as i32) & 64i32 != 0
}

fn ata_id_has_flush_ext(id: *const u16) -> bool {
if ((unsafe { *id.wrapping_offset(83 as isize) }) as i32) & 49152 != 16384 {
return false;
}
((unsafe { *id.wrapping_offset(83 as isize) }) as i32) & 8192i32 != 0
}

fn ata_id_has_lba48(mut id: *const u16) -> bool {
if ((unsafe { *id.wrapping_offset(83 as isize) }) as i32) & 49152 != 16384 {
return false;
}
if ata_id_u64!(id, 100i32) == 0 {
return false;
}
((unsafe { *id.wrapping_offset(83 as isize) }) as i32) & 1024i32 != 0
}

fn ata_id_hpa_enabled(id: *const u16) -> bool {
// Yes children, word 83 valid bits cover word 82 data
if ((unsafe { *id.wrapping_offset(83 as isize) }) as i32) & 49152 != 16384 {
return false;
}
// And 87 covers 85-87
if ((unsafe { *id.wrapping_offset(87 as isize) }) as i32) & 49152 != 16384 {
return false;
}
// Check command sets enabled as well as supported
if ((unsafe { *id.wrapping_offset(85 as isize) }) as i32) & 1024i32 == 0 {
return false;
}
((unsafe { *id.wrapping_offset(82 as isize) }) as i32) & 1024i32 != 0
}

fn ata_id_has_read_log_dma_ext(id: *const u16) -> bool {
// Word 86 must have bit 15 set
if ((unsafe { *id.wrapping_offset(86 as isize) }) as i32) & 32768i32 == 0 {
return false;
}
// READ LOG DMA EXT support can be signaled either from word 119
// or from word 120. The format is the same for both words: Bit
// 15 must be cleared, bit 14 set and bit 3 set.
if ((unsafe { *id.wrapping_offset(119 as isize) }) as i32) & 49160 == 16392 || ((unsafe { *id.wrapping_offset(120 as isize) }) as i32) & 49160 == 16392 {
return true;
}
false
}

fn ata_id_has_sense_reporting(id: *const u16) -> bool {
if (((unsafe { *id.wrapping_offset(86 as isize) }) as i32) as u64) & BIT!(15i32) == 0 {
return false;
}
if (((unsafe { *id.wrapping_offset(119 as isize) }) as i32) as u64) & (BIT!(15i32) | BIT!(14i32)) != BIT!(14i32) {
return false;
}
(((unsafe { *id.wrapping_offset(119 as isize) }) as i32) as u64) & BIT!(6i32) != 0
}

fn ata_id_sense_reporting_enabled(id: *const u16) -> bool {
if !ata_id_has_sense_reporting(id) {
return false;
}
// ata_id_has_sense_reporting() == true, word 86 must have bit 15 set
if (((unsafe { *id.wrapping_offset(120 as isize) }) as i32) as u64) & (BIT!(15i32) | BIT!(14i32)) != BIT!(14i32) {
return false;
}
(((unsafe { *id.wrapping_offset(120 as isize) }) as i32) as u64) & BIT!(6i32) != 0
}

fn ata_id_major_version(id: *const u16) -> u32 {
let mut mver: u32 = 14;
if ((unsafe { *id.wrapping_offset(80 as isize) }) as i32) == 65535 {
return 0;
}
while mver >= 1 {
if ((unsafe { *id.wrapping_offset(80 as isize) }) as i32) & 1i32 << mver != 0 {
break;
}
mver = mver.wrapping_sub(1);
}
mver
}

fn ata_id_is_sata(id: *const u16) -> bool {
// See if word 93 is 0 AND drive is at least ATA-5 compatible
// verifying that word 80 by casting it to a signed type --
// this trick allows us to filter out the reserved values of
// 0x0000 and 0xffff along with the earlier ATA revisions...
if ((unsafe { *id.wrapping_offset(93 as isize) }) as i32) == 0 && (((unsafe { *id.wrapping_offset(80 as isize) }) as i16) as i32) >= 32 {
return true;
}
false
}

fn ata_id_has_tpm(id: *const u16) -> bool {
// The TPM bits are only valid on ATA8
if ata_id_major_version(id) < 8 {
return false;
}
if ((unsafe { *id.wrapping_offset(48 as isize) }) as i32) & 49152 != 16384 {
return false;
}
((unsafe { *id.wrapping_offset(48 as isize) }) as i32) & 1i32 != 0
}

fn ata_id_has_trusted(id: *const u16) -> bool {
if ata_id_major_version(id) <= 7 {
return false;
}
((unsafe { *id.wrapping_offset(48 as isize) }) as i32) & 1i32 != 0
}

fn ata_id_has_ncq_send_and_recv(id: *const u16) -> bool {
(((unsafe { *id.wrapping_offset(77 as isize) }) as i32) as u64) & BIT!(6i32) != 0
}

fn ata_id_has_ncq_non_data(id: *const u16) -> bool {
(((unsafe { *id.wrapping_offset(77 as isize) }) as i32) as u64) & BIT!(5i32) != 0
}

fn ata_id_has_ncq_prio(id: *const u16) -> bool {
(((unsafe { *id.wrapping_offset(76 as isize) }) as i32) as u64) & BIT!(12i32) != 0
}

fn ata_id_current_chs_valid(id: *const u16) -> bool {
// For ATA-1 devices, if the INITIALIZE DEVICE PARAMETERS command
// has not been issued to the device then the values of
// id[ATA_ID_CUR_CYLS] to id[ATA_ID_CUR_SECTORS] are vendor specific.
return ((unsafe { *id.wrapping_offset(53 as isize) }) as i32) & 1 != 0 && (unsafe { *id.wrapping_offset(54 as isize) }) != 0 && (unsafe { *id.wrapping_offset(55 as isize) }) != 0 && ((unsafe { *id.wrapping_offset(55 as isize) }) as i32) <= 16 && (unsafe { *id.wrapping_offset(56 as isize) }) != 0; // Current translation valid
// cylinders in current translation
// heads in current translation
// sectors in current translation
}

fn ata_id_is_cfa(id: *const u16) -> bool {
if ((unsafe { *id.wrapping_offset(0 as isize) }) as i32) == 33930 || ((unsafe { *id.wrapping_offset(0 as isize) }) as i32) == 33866 {
return true;
}
// Traditional CF
// Delkin Devices CF
// CF specs don't require specific value in the word 0 anymore and yet
// they forbid to report the ATA version in the word 80 and require the
// CFA feature set support to be indicated in the word 83 in this case.
// Unfortunately, some cards only follow either of this requirements,
// and while those that don't indicate CFA feature support need some
// sort of quirk list, it seems impractical for the ones that do...
((unsafe { *id.wrapping_offset(83 as isize) }) as i32) & 49156 == 16388
}

fn ata_id_zoned_cap(id: *const u16) -> u8 {
(((unsafe { *id.wrapping_offset(69 as isize) }) as i32) & 3) as u8
}

fn ata_drive_40wire(dev_id: *const u16) -> bool {
if ata_id_is_sata(dev_id) {
return false;
}
// SATA
if ((unsafe { *dev_id.wrapping_offset(93 as isize) }) as i32) & 57344 == 24576 {
return false;
}
// 80 wire
true
}

fn ata_drive_40wire_relaxed(dev_id: *const u16) -> bool {
if ((unsafe { *dev_id.wrapping_offset(93 as isize) }) as i32) & 8192 == 8192 {
return false;
}
// 80 wire
true
}

fn atapi_cdb_len(dev_id: *const u16) -> i32 {
let tmp: u16 = (((unsafe { *dev_id.wrapping_offset(0 as isize) }) as i32) & 3) as u16;
match tmp as i32 {
0 => {
return 12;
}
1 => {
return 16;
}
_ => {
return 1i32.wrapping_neg();
}
}
unsafe { core::mem::zeroed() }
}

fn atapi_command_packet_set(dev_id: *const u16) -> i32 {
((unsafe { *dev_id.wrapping_offset(0 as isize) }) as i32) >> 8i32 & 31
}

fn atapi_id_dmadir(dev_id: *const u16) -> bool {
ata_id_major_version(dev_id) >= 7 && ((unsafe { *dev_id.wrapping_offset(62 as isize) }) as i32) & 32768 != 0
}

