/// ata_msleep - ATA EH owner aware msleep
/// @ap: ATA port to attribute the sleep to
/// @msecs: duration to sleep in milliseconds
///
/// Sleeps @msecs.  If the current task is owner of @ap's EH, the
/// ownership is released before going to sleep and reacquired
/// after the sleep is complete.  IOW, other ports sharing the
/// @ap->host will be allowed to own the EH while this task is
/// sleeping.
///
/// LOCKING:
/// Might sleep.
#[unsafe(no_mangle)]
#[unsafe(link_section = ".text.slate_distinct.libata_core.ata_msleep")]
extern "C" fn ata_msleep(ap: *mut ata_port, msecs: u32) {
let mut owns_eh: bool = false;
owns_eh = !ap.is_null() && (unsafe { (*(*ap).host).eh_owner }) == get_current();
if owns_eh {
unsafe { ata_eh_release(ap) };
}
if msecs < 20 {
let usecs: u64 = (msecs as i64).wrapping_mul(1000) as u64;
usleep_range(usecs, usecs.wrapping_add(50));
} else {
unsafe { msleep(msecs) };
}
if owns_eh {
unsafe { ata_eh_acquire(ap) };
}
}

